-- Isolated TV DexterH4ck schema. No public/clinic tables are modified.
create schema if not exists tv_dexter;
create table if not exists tv_dexter.categories (id text primary key,name text not null,description text not null default '',sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists tv_dexter.catalog_items (id uuid primary key default gen_random_uuid(),category_id text not null references tv_dexter.categories(id) on update cascade,title text not null,synopsis text not null default '',poster_url text,backdrop_url text,stream_url text,stream_type text not null default 'hls' check(stream_type in ('hls','dash','mp4','roku')),source_name text,release_year integer,duration_seconds integer,is_live boolean not null default false,featured boolean not null default false,published boolean not null default false,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists catalog_items_category_published_idx on tv_dexter.catalog_items(category_id,published,is_live);
create table if not exists tv_dexter.favorites(user_id uuid not null references auth.users(id) on delete cascade,item_id uuid not null references tv_dexter.catalog_items(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,item_id));
create table if not exists tv_dexter.playback_progress(user_id uuid not null references auth.users(id) on delete cascade,item_id uuid not null references tv_dexter.catalog_items(id) on delete cascade,position_seconds integer not null default 0 check(position_seconds>=0),duration_seconds integer,completed boolean not null default false,updated_at timestamptz not null default now(),primary key(user_id,item_id));
create table if not exists tv_dexter.ingestion_jobs(id uuid primary key default gen_random_uuid(),provider text not null,status text not null default 'queued' check(status in ('queued','running','succeeded','failed')),input_ref text,result jsonb not null default '{}'::jsonb,error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into tv_dexter.categories(id,name,description,sort_order) values ('inicio','Inicio','Selección destacada',0),('en-vivo','En vivo','Canales en directo autorizados',1),('peliculas','Películas','Películas del catálogo',2),('series','Series','Series y episodios',3),('deportes','Deportes','Eventos y canales deportivos autorizados',4),('infantil','Infantil','Contenido para toda la familia',5),('documentales','Documentales','Ciencia, historia y naturaleza',6),('xuper','Xuper','Integraciones Xuper autorizadas',7),('plugins','Plugins','Fuentes y complementos compatibles',8) on conflict(id) do nothing;
alter table tv_dexter.categories enable row level security; alter table tv_dexter.catalog_items enable row level security; alter table tv_dexter.favorites enable row level security; alter table tv_dexter.playback_progress enable row level security; alter table tv_dexter.ingestion_jobs enable row level security;
create policy "Public reads active categories" on tv_dexter.categories for select to anon,authenticated using(active=true);
create policy "Public reads published catalog" on tv_dexter.catalog_items for select to anon,authenticated using(published=true);
create policy "Users read own favorites" on tv_dexter.favorites for select to authenticated using((select auth.uid())=user_id);
create policy "Users add own favorites" on tv_dexter.favorites for insert to authenticated with check((select auth.uid())=user_id);
create policy "Users remove own favorites" on tv_dexter.favorites for delete to authenticated using((select auth.uid())=user_id);
create policy "Users read own playback" on tv_dexter.playback_progress for select to authenticated using((select auth.uid())=user_id);
create policy "Users insert own playback" on tv_dexter.playback_progress for insert to authenticated with check((select auth.uid())=user_id);
create policy "Users update own playback" on tv_dexter.playback_progress for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "Deny client ingestion access" on tv_dexter.ingestion_jobs for all to anon,authenticated using(false) with check(false);
revoke all on schema tv_dexter from public,anon,authenticated; grant usage on schema tv_dexter to anon,authenticated; grant select on tv_dexter.categories,tv_dexter.catalog_items to anon,authenticated; grant select,insert,delete on tv_dexter.favorites to authenticated; grant select,insert,update on tv_dexter.playback_progress to authenticated; revoke all on tv_dexter.ingestion_jobs from anon,authenticated;